import dart:convert; import dart:io; void main() async { var req = await HttpClient().postUrl(Uri.parse(https://api.cobalt.tools/api/json)); req.headers.set(Accept, application/json); req.headers.set(Content-Type, application/json); req.headers.set(User-Agent, Mozilla/5.0); req.add(utf8.encode(jsonEncode({url: https://www.youtube.com/watch?v=dQw4w9WgXcQ, isAudioOnly: true}))); var res = await req.close(); print(res.statusCode); var body = await res.transform(utf8.decoder).join(); print(body); }
